 const r=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,1.8));const s=new THREE.Scene(),cam=new THREE.PerspectiveCamera(40,1,.1,100);cam.position.set(0,0,16);s.add(new THREE.HemisphereLight(0xffffff,0x254653,2.5));const light=new THREE.DirectionalLight(0xffecc8,3);light.position.set(-6,6,10);s.add(light);const group=new THREE.Group();s.add(group);const globe=new THREE.Mesh(new THREE.SphereGeometry(4.5,64,48),new THREE.MeshStandardMaterial({map:earthTexture,metalness:.12,roughness:.5}));group.add(globe);
 const water=new THREE.Mesh(new THREE.SphereGeometry(4.525,64,48),new THREE.ShaderMaterial({uniforms:{clock:{value:0}},transparent:true,depthWrite:false,vertexShader:'uniform float clock;varying vec3 vN;varying vec3 vP;void main(){vec3 p=position;p+=normal*(sin(p.y*4.+clock*.8)*.035+sin((p.x+p.z)*7.-clock)*.018);vN=normalize(normalMatrix*normal);vP=(modelMatrix*vec4(p,1.)).xyz;gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}',fragmentShader:'uniform float clock;varying vec3 vN;varying vec3 vP;void main(){vec3 view=normalize(cameraPosition-vP);float fres=pow(1.-max(0.,dot(normalize(vN),view)),2.);float wave=.5+.5*sin(vP.y*8.+vP.x*4.+clock*1.2)+.35*sin(vP.z*15.-clock*1.7);vec3 c=mix(vec3(.01,.08,.15),vec3(.02,.36,.5),.5+wave*.12);c+=vec3(.35,.9,.9)*fres*.8;gl_FragColor=vec4(c,.38+fres*.4);}'}));group.add(water);const tideRings=[4.72,4.94,5.16,5.38].map((radius,i)=>{const ring=new THREE.Mesh(new THREE.TorusGeometry(radius,.035+(i===1?.02:0),8,128),new THREE.MeshBasicMaterial({color:i%2?0xa4f4ee:0x3fc7e5,transparent:true,opacity:.28,depthWrite:false}));ring.rotation.set(.35+i*.27,i*.71,-.2+i*.19);group.add(ring);return ring;});
